"use client";

import { useState } from "react";

import { cn } from "@/lib/utils";

import { Composer } from "./composer";
import { CommentThread } from "./thread";
import type { CommentBoxProps, CommentItem, ThreadActions } from "./types";
import { createId, mapThread, toggleReaction } from "./utils";

import "@/components/editor/style.css";
import "@/components/static-renderer/style.css";

export const CommentBox = ({
  className,
  currentUser = { id: "you", name: "You" },
  initialComments = [],
  onDelete,
  onPost,
  onReact,
  placeholder = "Add a comment…",
  title = "Comments",
}: CommentBoxProps) => {
  const [comments, setComments] = useState<CommentItem[]>(initialComments);
  const total = comments.reduce(
    (sum, c) => sum + 1 + (c.replies?.length ?? 0),
    0
  );

  const actions: ThreadActions = {
    currentUser,
    post: (content, parentId) => {
      onPost?.(content, parentId);
      const comment: CommentItem = {
        author: currentUser,
        content,
        createdAt: new Date().toISOString(),
        id: createId(),
      };
      setComments((prev) =>
        parentId
          ? prev.map((c) =>
              c.id === parentId
                ? { ...c, replies: [...(c.replies ?? []), comment] }
                : c
            )
          : [...prev, comment]
      );
    },
    react: (id, emoji) => {
      onReact?.(id, emoji);
      setComments((prev) =>
        mapThread(prev, (c) =>
          c.id === id
            ? { ...c, reactions: toggleReaction(c.reactions ?? [], emoji) }
            : c
        )
      );
    },
    remove: (id) => {
      onDelete?.(id);
      setComments((prev) => mapThread(prev, (c) => (c.id === id ? null : c)));
    },
  };

  return (
    <section
      className={cn(
        "bg-background flex flex-col overflow-hidden rounded-2xl border",
        className
      )}
    >
      <header className="flex shrink-0 items-center gap-2 border-b px-4 py-3">
        <h3 className="text-sm font-semibold">{title}</h3>
        <span className="bg-muted text-muted-foreground rounded-full px-2 py-0.5 text-xs tabular-nums">
          {total}
        </span>
      </header>
      {comments.length > 0 ? (
        <ul className="flex min-h-0 flex-1 flex-col overflow-y-auto py-1">
          {comments.map((comment) => (
            <CommentThread
              key={comment.id}
              actions={actions}
              comment={comment}
            />
          ))}
        </ul>
      ) : (
        <p className="text-muted-foreground px-4 py-8 text-center text-sm">
          No comments yet. Start the conversation.
        </p>
      )}
      <Composer
        author={currentUser}
        className="shrink-0 border-t px-4 py-4"
        onPost={(content) => actions.post(content)}
        placeholder={placeholder}
      />
    </section>
  );
};

export type {
  CommentAuthor,
  CommentBoxProps,
  CommentItem,
  CommentReaction,
  CommentReply,
} from "./types";

"use client";

import { RichTextEditor } from "@/components/editor";
import type { JSONContent } from "@tiptap/core";
import { Placeholder } from "@tiptap/extension-placeholder";
import { useEditor, useEditorState } from "@tiptap/react";
import type { Editor } from "@tiptap/react";
import {
  Bold,
  Check,
  Code,
  Italic,
  List,
  Strikethrough,
  Type,
} from "lucide-react";
import { useCallback, useEffect, useRef } from "react";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Kbd, KbdGroup } from "@/components/ui/kbd";
import { cn } from "@/lib/utils";

import type { CommentAuthor } from "./types";
import { EXTENSIONS, ITEM, initials } from "./utils";

export const UserAvatar = ({
  author,
  small = false,
}: {
  author: CommentAuthor;
  small?: boolean;
}) => (
  <Avatar className={small ? "size-7" : "size-8"}>
    {author.avatar && <AvatarImage alt={author.name} src={author.avatar} />}
    <AvatarFallback className="text-xs font-medium">
      {initials(author.name)}
    </AvatarFallback>
  </Avatar>
);

const FORMATS = [
  { Icon: Bold, label: "Bold", mark: "bold", toggle: "toggleBold" },
  { Icon: Italic, label: "Italic", mark: "italic", toggle: "toggleItalic" },
  {
    Icon: Strikethrough,
    label: "Strikethrough",
    mark: "strike",
    toggle: "toggleStrike",
  },
  { Icon: Code, label: "Code", mark: "code", toggle: "toggleCode" },
  {
    Icon: List,
    label: "Bullet list",
    mark: "bulletList",
    toggle: "toggleBulletList",
  },
] as const;

const FormatMenu = ({ editor }: { editor: Editor | null }) => {
  const refocus = useRef(false);
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          aria-label="Formatting"
          className="text-muted-foreground sm:hidden"
          onFocus={() => {
            if (refocus.current) {
              refocus.current = false;
              editor?.commands.focus();
            }
          }}
          size="icon-sm"
          variant="ghost"
        >
          <Type />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="min-w-40 p-1">
        {FORMATS.map(({ Icon, label, mark, toggle }) => (
          <DropdownMenuItem
            key={mark}
            className={ITEM}
            onClick={() => {
              refocus.current = true;
              editor?.chain().focus()[toggle]().run();
            }}
          >
            <Icon />
            {label}
            {editor?.isActive(mark) && <Check className="ml-auto" />}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

export const Composer = ({
  author,
  autoFocus = false,
  className,
  initialContent,
  onCancel,
  onPost,
  placeholder,
  submitLabel = "Comment",
}: {
  author: CommentAuthor;
  autoFocus?: boolean;
  className?: string;
  initialContent?: JSONContent;
  onCancel?: () => void;
  onPost: (content: JSONContent) => void;
  placeholder: string;
  submitLabel?: string;
}) => {
  const handlers = useRef<{ cancel?: () => void; post: () => void } | null>(
    null
  );

  const editor = useEditor({
    autofocus: autoFocus ? "end" : false,
    content: initialContent ?? "",
    editorProps: {
      handleKeyDown: (_view, event) => {
        if (event.key === "Escape" && handlers.current?.cancel) {
          handlers.current.cancel();
          return true;
        }
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
          handlers.current?.post();
          return true;
        }
        return false;
      },
    },
    extensions: [...EXTENSIONS, Placeholder.configure({ placeholder })],
    immediatelyRender: false,
    shouldRerenderOnTransaction: false,
  });

  const isEmpty =
    useEditorState({
      editor,
      selector: ({ editor: e }) => !e || e.isEmpty,
    }) ?? true;

  const post = useCallback(() => {
    if (!editor || editor.isDestroyed || editor.isEmpty) {
      return;
    }
    onPost(editor.getJSON());
    editor.commands.clearContent();
  }, [editor, onPost]);

  useEffect(() => {
    handlers.current = { cancel: onCancel, post };
  }, [onCancel, post]);

  const mod = /Mac|iPhone|iPad/.test(globalThis.navigator?.userAgent ?? "")
    ? "⌘"
    : "Ctrl";

  return (
    <div className={cn("flex gap-3", className)}>
      <div className="hidden sm:block">
        <UserAvatar author={author} />
      </div>
      <RichTextEditor
        editor={editor}
        variant="compact"
        className="bg-background focus-within:border-ring focus-within:ring-ring/20 min-w-0 flex-1 rounded-xl! border shadow-xs transition-shadow focus-within:ring-3"
      >
        <RichTextEditor.Content className="[&_.ProseMirror]:min-h-16! [&_.ProseMirror]:px-3! [&_.ProseMirror]:py-2.5! [&_.ProseMirror]:text-base sm:[&_.ProseMirror]:text-sm" />
        <div className="flex flex-wrap items-center gap-x-2 gap-y-1 px-1.5 pb-1.5">
          <FormatMenu editor={editor} />
          <RichTextEditor.ControlsGroup className="max-sm:hidden!">
            <RichTextEditor.Bold />
            <RichTextEditor.Italic />
            <RichTextEditor.Strikethrough />
            <RichTextEditor.Code />
            <RichTextEditor.BulletList />
          </RichTextEditor.ControlsGroup>
          <div className="ml-auto flex items-center gap-2">
            <KbdGroup className="text-muted-foreground hidden sm:inline-flex">
              <Kbd suppressHydrationWarning>{mod}</Kbd>
              <Kbd>Enter</Kbd>
            </KbdGroup>
            {onCancel && (
              <Button
                className="rounded-lg"
                onClick={onCancel}
                size="sm"
                variant="ghost"
              >
                Cancel
              </Button>
            )}
            <Button
              className="rounded-lg"
              disabled={isEmpty}
              onClick={post}
              size="sm"
            >
              {submitLabel}
            </Button>
          </div>
        </div>
      </RichTextEditor>
    </div>
  );
};

"use client";

import { StaticRenderer } from "@/components/static-renderer";
import { generateText } from "@tiptap/core";
import {
  ChevronDown,
  Copy,
  MoreHorizontal,
  SmilePlus,
  Trash2,
} from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";

import { Composer, UserAvatar } from "./composer";
import type {
  CommentItem,
  CommentReaction,
  CommentReply,
  ThreadActions,
} from "./types";
import { EMOJIS, EXTENSIONS, ITEM, mention, timeAgo } from "./utils";

const EmojiPicker = ({ onPick }: { onPick: (emoji: string) => void }) => {
  const [open, setOpen] = useState(false);
  return (
    <Popover onOpenChange={setOpen} open={open}>
      <PopoverTrigger asChild>
        <Button
          aria-label="Add reaction"
          className="text-muted-foreground size-7 rounded-full border"
          size="icon-sm"
          variant="ghost"
        >
          <SmilePlus className="size-3.5" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="flex w-auto gap-0.5 rounded-full p-1"
      >
        {EMOJIS.map((emoji) => (
          <button
            key={emoji}
            aria-label={`React with ${emoji}`}
            className="hover:bg-accent flex size-8 items-center justify-center rounded-full text-base transition-transform active:scale-96"
            onClick={() => {
              onPick(emoji);
              setOpen(false);
            }}
            type="button"
          >
            {emoji}
          </button>
        ))}
      </PopoverContent>
    </Popover>
  );
};

const CommentMenu = ({
  canDelete,
  onCopy,
  onDelete,
}: {
  canDelete: boolean;
  onCopy: () => void;
  onDelete: () => void;
}) => (
  <DropdownMenu>
    <DropdownMenuTrigger asChild>
      <Button
        aria-label="Comment options"
        className="text-muted-foreground size-7 opacity-0 transition-opacity group-hover:opacity-100 focus-visible:opacity-100 data-[state=open]:opacity-100 [@media(hover:none)]:opacity-100"
        size="icon-sm"
        variant="ghost"
      >
        <MoreHorizontal className="size-4" />
      </Button>
    </DropdownMenuTrigger>
    <DropdownMenuContent align="end" className="min-w-36 p-1">
      <DropdownMenuItem className={ITEM} onClick={onCopy}>
        <Copy />
        Copy text
      </DropdownMenuItem>
      {canDelete && (
        <DropdownMenuItem
          className={ITEM}
          onClick={onDelete}
          variant="destructive"
        >
          <Trash2 />
          Delete
        </DropdownMenuItem>
      )}
    </DropdownMenuContent>
  </DropdownMenu>
);

const Reactions = ({
  onReact,
  reactions,
}: {
  onReact: (emoji: string) => void;
  reactions: CommentReaction[];
}) => (
  <>
    {reactions.map((reaction) => (
      <button
        key={reaction.emoji}
        aria-pressed={reaction.reacted ?? false}
        className={cn(
          "flex h-7 items-center gap-1 rounded-full border px-2 text-xs tabular-nums transition-colors active:scale-96",
          reaction.reacted
            ? "border-primary/30 bg-primary/10 text-foreground"
            : "hover:bg-accent text-muted-foreground"
        )}
        onClick={() => onReact(reaction.emoji)}
        type="button"
      >
        <span className="text-sm">{reaction.emoji}</span>
        {reaction.count}
      </button>
    ))}
    <EmojiPicker onPick={onReact} />
  </>
);

const CommentBody = ({
  actions,
  children,
  comment,
  onReply,
  small,
  stem = false,
}: {
  actions: ThreadActions;
  children?: React.ReactNode;
  comment: CommentReply;
  onReply: () => void;
  small: boolean;
  stem?: boolean;
}) => (
  <div className="group flex gap-3">
    <div className="flex flex-col items-center">
      <UserAvatar author={comment.author} small={small} />
      {stem && <div className="bg-border mt-1 w-0.5 flex-1 rounded-full" />}
    </div>
    <div className="min-w-0 flex-1">
      <div className="flex items-center gap-2">
        <span className="truncate text-sm font-medium">
          {comment.author.name}
        </span>
        <time
          className="text-muted-foreground shrink-0 text-xs"
          dateTime={comment.createdAt}
          suppressHydrationWarning
          title={new Date(comment.createdAt).toLocaleString()}
        >
          {timeAgo(comment.createdAt)}
        </time>
        <div className="ml-auto">
          <CommentMenu
            canDelete={comment.author.id === actions.currentUser.id}
            onCopy={() =>
              navigator.clipboard.writeText(
                generateText(comment.content, EXTENSIONS)
              )
            }
            onDelete={() => actions.remove(comment.id)}
          />
        </div>
      </div>
      <StaticRenderer
        className="text-foreground/90 -mt-1 text-sm [&_code]:text-[0.85em]"
        content={comment.content}
        extensions={EXTENSIONS}
      />
      <div className="mt-1.5 flex flex-wrap items-center gap-1">
        <Reactions
          onReact={(emoji) => actions.react(comment.id, emoji)}
          reactions={comment.reactions ?? []}
        />
        <Button
          className="text-muted-foreground h-7 rounded-full px-2.5 text-xs font-medium"
          onClick={onReply}
          size="sm"
          variant="ghost"
        >
          Reply
        </Button>
      </div>
      {children}
    </div>
  </div>
);

const ReplyToggle = ({
  count,
  onToggle,
  open,
}: {
  count: number;
  onToggle: () => void;
  open: boolean;
}) => (
  <Button
    aria-expanded={open}
    className="text-primary -ml-2.5 h-8 w-fit gap-1.5 rounded-full px-2.5 text-[13px] font-medium"
    onClick={onToggle}
    size="sm"
    variant="ghost"
  >
    {open ? "Hide replies" : `${count} ${count === 1 ? "reply" : "replies"}`}
    <ChevronDown className={cn("transition-transform", open && "rotate-180")} />
  </Button>
);

export const CommentThread = ({
  actions,
  comment,
}: {
  actions: ThreadActions;
  comment: CommentItem;
}) => {
  const [open, setOpen] = useState(false);
  const [target, setTarget] = useState<CommentReply | null>(null);
  const replies = comment.replies ?? [];
  const showReplies = open && replies.length > 0;

  const replyBox = (to: CommentReply) =>
    target?.id === to.id && (
      <Composer
        author={actions.currentUser}
        autoFocus
        className="mt-2"
        initialContent={
          to.id === comment.id ? undefined : mention(to.author.name)
        }
        onCancel={() => setTarget(null)}
        onPost={(content) => {
          actions.post(content, comment.id);
          setTarget(null);
          setOpen(true);
        }}
        placeholder={`Reply to ${to.author.name}…`}
        submitLabel="Reply"
      />
    );

  return (
    <li className="animate-in fade-in px-4 py-3 duration-200">
      <CommentBody
        actions={actions}
        comment={comment}
        onReply={() => setTarget(comment)}
        small={false}
        stem={showReplies}
      >
        {replyBox(comment)}
      </CommentBody>
      <div className="pl-11">
        {showReplies && (
          <ul className="flex flex-col">
            {replies.map((reply, index) => (
              <li
                key={reply.id}
                className="animate-in fade-in relative pt-3 duration-200"
              >
                <span
                  aria-hidden
                  className="border-border absolute top-0 -left-[29px] h-[26px] w-[25px] rounded-bl-xl border-b-2 border-l-2"
                />
                {index < replies.length - 1 && (
                  <span
                    aria-hidden
                    className="bg-border absolute top-0 bottom-0 -left-[29px] w-0.5"
                  />
                )}
                <CommentBody
                  actions={actions}
                  comment={reply}
                  onReply={() => setTarget(reply)}
                  small
                >
                  {replyBox(reply)}
                </CommentBody>
              </li>
            ))}
          </ul>
        )}
        {replies.length > 0 && (
          <ReplyToggle
            count={replies.length}
            onToggle={() => setOpen((value) => !value)}
            open={open}
          />
        )}
      </div>
    </li>
  );
};

import type { JSONContent } from "@tiptap/core";

export interface CommentAuthor {
  avatar?: string;
  id: string;
  name: string;
}

export interface CommentReaction {
  count: number;
  emoji: string;
  reacted?: boolean;
}

export interface CommentReply {
  author: CommentAuthor;
  createdAt: string;
  content: JSONContent;
  id: string;
  reactions?: CommentReaction[];
}

export interface CommentItem extends CommentReply {
  replies?: CommentReply[];
}

export interface CommentBoxProps {
  className?: string;
  currentUser?: CommentAuthor;
  initialComments?: CommentItem[];
  onDelete?: (id: string) => void;
  onPost?: (content: JSONContent, parentId?: string) => void;
  onReact?: (id: string, emoji: string) => void;
  placeholder?: string;
  title?: string;
}

export interface ThreadActions {
  currentUser: CommentAuthor;
  post: (content: JSONContent, parentId?: string) => void;
  react: (id: string, emoji: string) => void;
  remove: (id: string) => void;
}

import type { JSONContent } from "@tiptap/core";
import { StarterKit } from "@tiptap/starter-kit";

import type { CommentItem, CommentReaction, CommentReply } from "./types";

export const EMOJIS = ["👍", "❤️", "🎉", "😄", "👀", "🚀"];

export const ITEM =
  "rounded-md py-1 text-[13px] [&_svg:not([class*='size-'])]:size-3.5";

export const EXTENSIONS = [
  StarterKit.configure({
    blockquote: false,
    codeBlock: false,
    heading: false,
    horizontalRule: false,
  }),
];

const UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 31_536_000],
  ["month", 2_592_000],
  ["week", 604_800],
  ["day", 86_400],
  ["hour", 3600],
  ["minute", 60],
];

export const timeAgo = (iso: string) => {
  const seconds = (new Date(iso).getTime() - Date.now()) / 1000;
  const format = new Intl.RelativeTimeFormat(undefined, { numeric: "auto" });
  const match = UNITS.find(([, size]) => Math.abs(seconds) >= size);
  return match
    ? format.format(Math.round(seconds / match[1]), match[0])
    : "just now";
};

export const initials = (name: string) =>
  name
    .split(" ")
    .map((part) => part[0])
    .filter(Boolean)
    .slice(0, 2)
    .join("")
    .toUpperCase();

export const toggleReaction = (
  reactions: CommentReaction[],
  emoji: string
): CommentReaction[] => {
  const existing = reactions.find((r) => r.emoji === emoji);
  if (!existing) {
    return [...reactions, { count: 1, emoji, reacted: true }];
  }
  return reactions
    .map((r) =>
      r.emoji === emoji
        ? { ...r, count: r.count + (r.reacted ? -1 : 1), reacted: !r.reacted }
        : r
    )
    .filter((r) => r.count > 0);
};

export const mention = (name: string): JSONContent => ({
  content: [
    { content: [{ text: `@${name} `, type: "text" }], type: "paragraph" },
  ],
  type: "doc",
});

export const createId = () =>
  globalThis.crypto?.randomUUID?.() ??
  `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;

const mapLevel = <T extends CommentReply>(
  list: T[],
  update: (comment: CommentReply) => CommentReply | null
): T[] =>
  list.flatMap((comment) => {
    const next = update(comment);
    return next ? [{ ...comment, ...next }] : [];
  });

export const mapThread = (
  list: CommentItem[],
  update: (comment: CommentReply) => CommentReply | null
): CommentItem[] =>
  mapLevel(list, update).map((comment) =>
    comment.replies
      ? { ...comment, replies: mapLevel(comment.replies, update) }
      : comment
  );
